from .client_controllers import LocalXgenClient, RemoteXgenClient
from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output, log_step, log_env_state
from .exceptions import InvalidConfigError


class xGen:
    """
    Controls the xGen device using the xgen-client interface.
    Provides an abstraction layer for both local and remote (via proxy VM) interactions with the xgen-client.

    *Important*: The xgen-client executable must be installed on the target VM.

    Download the xgen-client from:
    https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-xgen-release-local/

    xGen wiki:
    https://confluence.ext.net.nokia.com/display/XGEN/Introduction

    Usage example:
    # Example configuration for local mode
    config = {
        "xgen_client_mode": "local",
        "xgen_client_path": "/home/ute/xgen/xgen-client",
        "xgen_capture_ports": "SFP1",
        "xgen_server_ip": "192.168.255.1",
        "logs_dir": "/home/ute/TestCase_logs/"
    }

    # Initialize and set up xGen
    xgen_device = xGen()
    xgen_device.setup(config)

    # Start PCAP capture
    xgen_device.start_capture_pcap(pcap_filename="xgen_capture.pcap")

    # Stop PCAP capture
    xgen_device.stop_capture_pcap()

    # Close the xGen device
    xgen_device.close()
    """

    def __init__(self):
        self._xgen_client_mode = None
        self._xgen_client_path = None
        self._xgen_server_ip = None
        self._xgen_ports_to_capture = None
        self._proxy_ssh = None
        self._runner = None
        self._logs_dir = None

    @log_input_and_output
    def setup(self, config: dict):
        """
        :param config: Configuration dictionary containing the:
                       * xgen_client_mode: - how interaction with the xgen-client will be performed: either 'local' or 'remote' (via proxy VM).
                                             'local' - interact with xgen-client locally (xgen client installed on the same VM where this code runs).
                                             'remote' - interact with xgen-client via proxy VM (xgen client installed on remote VM).
                                                       Needs provide ssh details.
                                             Default is 'local'.
                       * xgen_client_path: Absolute path to the xgen-client executable. Default is '/home/ute/xgen/xgen-client'.
                       * xgen_capture_ports: Str or list of ports to capture e.g  'SFP1' or ['SFP1', 'SFP2']
                       * xgen_server_ip: IP address from which xGen is reachable on the VM. Default is '192.168.255.1'
                       * proxy_ssh: Details to established SSH proxy connection to remote VM. Mandatory if xgen_client_mode == 'remote'.
                                    The proxy_ssh dictionary should contain the following: host, username, and password e.g.
                                    "proxy_ssh": {"host": "10.42.100.100","username": "user","password": "pass"}
                      * logs_dir: Directory where the captured PCAP files and xgen-client log will be stored.

                      e.g.
                      config: {
                          "xgen_client_mode": "local",
                          "xgen_client_path": "/home/ute/xgen/xgen-client"
                          "xgen_capture_ports": "SFP1",
                          "xgen_server_ip": "192.168.255.1",
                          "logs_dir": "/home/ute/TestCase_logs/"
                      }

                      config: {
                          "xgen_client_mode": "remote",
                          "xgen_client_path": "/home/Desktop/xgen/xgen-client",
                          "xgen_capture_ports": ["SFP1", "SFP2"],
                          "xgen_server_ip": "192.168.255.1",
                          "proxy_ssh": {"host": "10.42.100.100",
                                        "username": "user",
                                        "password": "pass"},
                          "logs_dir": "/home/ute/TestCase_logs/"
                       }
        :type config: dict
        """
        self._validate_config(config)
        self._xgen_client_mode = config['xgen_client_mode']
        self._xgen_client_path = config['xgen_client_path']
        self._xgen_server_ip = config['xgen_server_ip']
        self._xgen_ports_to_capture = config['xgen_capture_ports']
        self._proxy_ssh = config['proxy_ssh'] if config['xgen_client_mode'] == 'remote' else False
        self._logs_dir = config['logs_dir']
        self._runner = self._create_xgen_runner(config)
        log_env_state(
            f"xGen setup: mode={self._xgen_client_mode}, "
            f"path={self._xgen_client_path}, "
            f"ports={self._xgen_ports_to_capture}, "
            f"server_ip={self._xgen_server_ip}, "
            f"proxy_ssh={self._proxy_ssh}, "
            f"logs_dir={self._logs_dir}"
        )

    @log_input_and_output
    def start_capture_pcap(self, pcap_save_path=None, pcap_filter=None, pcap_filename="xgen_capture.pcap"):
        """
        Starts capturing PCAP on the specified port(s).

        :param pcap_save_path: (Optional) Path where the PCAP file will be saved. If None, it will use the logs_dir from the config.
        :type pcap_save_path: str | None
        :param pcap_filter: (Optional) Filter to apply to the PCAP capture (e.g. "ecpri.type == 0x05"). Default is None (no filter).
        :type pcap_filter: str | None
        :param pcap_filename: (Optional) Name of the PCAP file to save with extension. Default is "xgen_capture.pcap".
        :type pcap_filename: str
        """
        if pcap_save_path is None:
            pcap_save_path = self._logs_dir
        self._runner.start_capture_pcap(
            ports=self._xgen_ports_to_capture, pcap_save_path=pcap_save_path, pcap_filter=pcap_filter, pcap_filename=pcap_filename)
        log_step(f"Started PCAP capture on ports: {self._xgen_ports_to_capture} with filter: {pcap_filter}")

    @log_input_and_output
    def stop_capture_pcap(self):
        """
        Stops the PCAP capture.
        """
        self._runner.stop_capture()
        log_step(f"Stopped PCAP capture on ports: {self._xgen_ports_to_capture}")

    @log_input_and_output
    def close(self):
        """
        Closes the xGen.
        """
        self._runner.close()
        log_step("xGen device closed.")

    def _create_xgen_runner(self, config: dict):
        if config['xgen_client_mode'] == 'local':
            return LocalXgenClient(config)
        return RemoteXgenClient(config)

    def _validate_config(self, config: dict):
        required_keys = ['xgen_client_mode',
                         'xgen_client_path',
                         'xgen_capture_ports',
                         'xgen_server_ip',
                         'logs_dir']

        mode = config.get('xgen_client_mode')
        if mode not in ['local', 'remote']:
            raise InvalidConfigError(f"Unsupported xgen_client_mode: {mode}. Supported modes are 'local' and 'remote'.")
        if mode == 'remote':
            required_keys.append('proxy_ssh')

        missing = [key for key in required_keys if key not in config]
        if missing:
            raise InvalidConfigError(f"Missing required configuration keys: {', '.join(missing)}")
